import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"x.com thread — English (polyglot voice)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v0.5/x-thread-en.md","filePath":"announcements/v0.5/x-thread-en.md"}'),s={name:"announcements/v0.5/x-thread-en.md"};function i(n,e,l,c,h,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="x-com-thread-—-english-polyglot-voice" tabindex="-1">x.com thread — English (polyglot voice) <a class="header-anchor" href="#x-com-thread-—-english-polyglot-voice" aria-label="Permalink to &quot;x.com thread — English (polyglot voice)&quot;">​</a></h1><blockquote><p>Account ... <a href="https://x.com/cardene777" target="_blank" rel="noreferrer">@cardene777</a> Voice ... maker first-person (&quot;I built this&quot;) Video ... attach <code>assets/kiwa-promo-en.mp4</code> (7.0MB / 80s) to tweet [1/8] Limit ... ~280 chars per tweet Threads ... [1/8] … [8/8]</p></blockquote><hr><h2 id="_1-8-attach-mp4" tabindex="-1">[1/8] (attach mp4) <a class="header-anchor" href="#_1-8-attach-mp4" aria-label="Permalink to &quot;[1/8] (attach mp4)&quot;">​</a></h2><p>Just shipped kiwa v0.5 — a <strong>polyglot test toolchain</strong> that turns one Layer 1 spec into every test layer your stack actually needs: contract, API, component, e2e, a11y, visual.</p><p>Release-time Coverage + Mutation gates enforced by GitHub Actions.</p><p>80s overview ↓</p><p><a href="https://github.com/cardene777/kiwa" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa</a></p><p>#OSS #testing</p><hr><h2 id="_2-8" tabindex="-1">[2/8] <a class="header-anchor" href="#_2-8" aria-label="Permalink to &quot;[2/8]&quot;">​</a></h2><p>The pain point: your test stack is <strong>scattered across mismatched runners</strong> — Foundry / Hardhat for contracts, Vitest for unit + API, Playwright for e2e, Testing Library for components, axe-core for a11y, pixelmatch for visual, pytest for Python services.</p><p>kiwa fuses them into one chain.</p><hr><h2 id="_3-8" tabindex="-1">[3/8] <a class="header-anchor" href="#_3-8" aria-label="Permalink to &quot;[3/8]&quot;">​</a></h2><p>Six test surfaces, one toolchain:</p><ol><li>Contract (Foundry / Hardhat)</li><li>API integration (msw / supertest)</li><li>Component (8 framework adapters)</li><li>E2E (Playwright + anvil + viem)</li><li>A11y + Visual (axe-core / pixelmatch)</li><li>Data / CLI / Observability</li></ol><p>dApps and smart contracts are first-class — but so is everything else.</p><hr><h2 id="_4-8" tabindex="-1">[4/8] <a class="header-anchor" href="#_4-8" aria-label="Permalink to &quot;[4/8]&quot;">​</a></h2><p>Polyglot from day one:</p><ul><li><strong>TypeScript</strong> — 11 npm packages</li><li><strong>Python</strong> — 1 PyPI package (<code>kiwa-test-py</code>)</li><li><strong>Solidity</strong> — Foundry / Hardhat bridges</li></ul><p>Rust / Go on the roadmap. The whole point: spec <strong>once</strong>, generate test layers across the languages your stack actually uses.</p><hr><h2 id="_5-8" tabindex="-1">[5/8] <a class="header-anchor" href="#_5-8" aria-label="Permalink to &quot;[5/8]&quot;">​</a></h2><p>v0.5 headline: every one of the 11 npm packages now ships behind a <strong>release-time mutation gate</strong> with MSI ≥ 80 enforced by GitHub Actions.</p><p>• @kiwa-test/api → 96.06% • @kiwa-test/a11y → 93.62% • @kiwa-test/ui → 91.76% • all 11 packages ≥ 80%</p><p>Coverage gate (Lines 90+ / Branches 80+) holds too.</p><hr><h2 id="_6-8" tabindex="-1">[6/8] <a class="header-anchor" href="#_6-8" aria-label="Permalink to &quot;[6/8]&quot;">​</a></h2><p>The component-test adapter (<code>@kiwa-test/ui</code>) covers <strong>8 surfaces from one package</strong>:</p><p>React / Vue 3 / Svelte / SolidJS / Lit / Qwik / Angular + real Chromium via Playwright.</p><p>Same <code>mode + stop()</code> contract. Thin wrapper design = new adapters land in ~100 LOC.</p><hr><h2 id="_7-8" tabindex="-1">[7/8] <a class="header-anchor" href="#_7-8" aria-label="Permalink to &quot;[7/8]&quot;">​</a></h2><p>Design call worth flagging: per-package mutation thresholds. Pure-logic packages enforce 90 %; thin wrappers around third-party libs hold the line at 80 %. Lets you ship a tough gate without getting trapped by equivalent mutants.</p><hr><h2 id="_8-8" tabindex="-1">[8/8] <a class="header-anchor" href="#_8-8" aria-label="Permalink to &quot;[8/8]&quot;">​</a></h2><p>If your stack feels like it has too many runners and too few specs, try kiwa:</p><p>📖 README · <a href="https://github.com/cardene777/kiwa" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa</a> 💬 Discussions · <a href="https://github.com/cardene777/kiwa/discussions/451" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa/discussions/451</a> 📦 <code>npm install @kiwa-test/core</code> 🐍 <code>pip install kiwa-test-py</code></p><p>Issues / discussions / replies welcome 🌱</p>',41)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
